// Trusted Apple certificate material used to validate App Store Server Notifications.
// Base64 strings represent DER-encoded certificates fetched from Apple.
const APPLE_ROOT_CA_G3_BASE64 = "";

export const TRUSTED_APPLE_ROOT_CERTS = new Map<string, string>([
  [
    normalizeCertificateBase64(APPLE_ROOT_CA_G3_BASE64),
    derBase64ToPem(APPLE_ROOT_CA_G3_BASE64),
  ],
]);

export function normalizeCertificateBase64(input: string): string {
  return input.replace(/\s+/g, "");
}

// Converts a DER-encoded certificate in Base64 form into PEM format so crypto
// helpers (e.g. jose.importX509) can consume it.
export function derBase64ToPem(base64: string): string {
  const normalised = normalizeCertificateBase64(base64);
  const wrapped = normalised.match(/.{1,64}/g)?.join("\n") ?? normalised;
  return `-----BEGIN CERTIFICATE-----\n${wrapped}\n-----END CERTIFICATE-----\n`;
}
